previewCss:
.darma-loader-darma-b16-distillation-coil { --accent: var(--loader-color, #0891b2); --accent-2: var(--loader-secondary-color, #fbbf24); width: var(--loader-size, 122px); height: calc(var(--loader-size, 122px) * .74); position: relative; }
.darma-loader-darma-b16-distillation-coil .darma-loader-darma-b16-distillation-coil__pot { position: absolute; left: 2%; bottom: 6%; width: 26%; height: 34%; border-radius: 6px 6px 40% 40%; background: linear-gradient(color-mix(in srgb, #fff 20%, var(--accent)), var(--accent)); }
.darma-loader-darma-b16-distillation-coil .darma-loader-darma-b16-distillation-coil__jar { position: absolute; right: 2%; bottom: 6%; width: 22%; height: 30%; border-radius: 4px 4px 20% 20%; background: color-mix(in srgb, var(--accent-2) 25%, transparent); box-shadow: inset 0 0 0 2px color-mix(in srgb, var(--accent-2) 60%, transparent); overflow: hidden; }
.darma-loader-darma-b16-distillation-coil .darma-loader-darma-b16-distillation-coil__jar::after { content: ''; position: absolute; left: 0; right: 0; bottom: 0; height: 20%; background: var(--accent-2); animation: darma-loader-darma-b16-distillation-coil-still-collect calc(var(--loader-speed, 1s) * 4) ease-in-out infinite; }
.darma-loader-darma-b16-distillation-coil span { position: absolute; top: 12%; width: 15%; height: 44%; border-radius: 50%; box-shadow: inset 0 0 0 3px color-mix(in srgb, var(--accent) 55%, transparent); animation: darma-loader-darma-b16-distillation-coil-still-flow calc(var(--loader-speed, 1s) * 2) ease-in-out infinite; }
.darma-loader-darma-b16-distillation-coil span:nth-of-type(1) { left: 20%; }
.darma-loader-darma-b16-distillation-coil span:nth-of-type(2) { left: 33%; animation-delay: calc(var(--loader-speed, 1s) * .18); }
.darma-loader-darma-b16-distillation-coil span:nth-of-type(3) { left: 46%; animation-delay: calc(var(--loader-speed, 1s) * .36); }
.darma-loader-darma-b16-distillation-coil span:nth-of-type(4) { left: 59%; animation-delay: calc(var(--loader-speed, 1s) * .54); }
.darma-loader-darma-b16-distillation-coil span:nth-of-type(5) { left: 72%; animation-delay: calc(var(--loader-speed, 1s) * .72); }
@keyframes darma-loader-darma-b16-distillation-coil-still-flow { 0%, 100% { box-shadow: inset 0 0 0 3px color-mix(in srgb, var(--accent) 30%, transparent); transform: scale(1); } 40% { box-shadow: inset 0 0 0 3px var(--accent-2); transform: scale(1.07); } }
@keyframes darma-loader-darma-b16-distillation-coil-still-collect { 0% { height: 12%; } 80%, 100% { height: 78%; } }

